                    <h3>Seated</h3>
                    <span>86 poses</span>
                </div>
            </article>

            <!-- Row 2 -->
            <article class="category-card cat-leaning-stnd">
                <div class="card-icon">🧱</div>
                <div class="card-info">
                    <h3>Leaning — Standing</h3>
                    <span>49 poses</span>
                </div>
            </article>

            <article class="category-card cat-leaning-seat">
                <div class="card-icon">🙏</div>
                <div class="card-info">
                    <h3>Leaning — Seated</h3>
                    <span>30 poses</span>
                </div>
            </article>

            <!-- Row 3 -->
            <article class="category-card cat-kneeling">
                <div class="card-icon">🧘</div>
                <div class="card-info">
                    <h3>Kneeling</h3>
                    <span>32 poses</span>
                </div>
            </article>

            <article class="category-card cat-reclining">
                <div class="card-icon">🛋️</div>
                <div class="card-info">
                    <h3>Reclining</h3>
                    <span>56 poses</span>
                </div>
            </article>

            <!-- Row 4 -->
            <article class="category-card cat-dynamic">
                <div class="card-icon">🕺</div>
                <div class="card-info">
                    <h3>Dynamic</h3>
                    <span>30 poses</span>
                </div>
            </article>

            <article class="category-card cat-eccentric">
                <div class="card-icon">✨</div>
                <div class="card-info">
                    <h3>Eccentric</h3>
                    <span>44 poses</span>
                </div>
            </article>

             <!-- Row 5 (Partial) -->
             <article class="category-card cat-other">
                <div class="card-icon">❤️</div>
                <div class="card-info">
                    <h3>Couples</h3>
                    <span>12 poses</span>
                </div>
            </article>

            <article class="category-card cat-extra">
                <div class="card-icon">🏃</div>
                <div class="card-info">
                    <h3>Action</h3>
                    <span>21 poses</span>
                </div>
            </article>
        </div>
    </main>

    <!-- Floating Add Button -->
    <div class="fab-container">
        <button class="fab-btn" aria-label="Add New">+</button>
    </div>

    <!-- Bottom Navigation -->
    <nav class="bottom-nav">
        <a href="#" class="nav-item active">
            <div class="nav-icon">⌂</div>
            <span>Home</span>
        </a>
        <a href="#" class="nav-item">
            <div class="nav-icon">▦</div>
            <span>Poses</span>
        </a>
        <a href="#" class="nav-item nav-center">
            <div class="nav-center-circle">
                <span class="nav-center-icon">▣</span>
            </div>
            <span style="margin-top: 8px;">Gallery</span>
        </a>
        <a href="#" class="nav-item">
            <div class="nav-icon">📊</div>
            <span>Progress</span>
        </a>
        <a href="#" class="nav-item">
            <div class="nav-icon">👤</div>
            <span>Profile</span>
        </a>
    </nav>

</body>
</html>
